import hmac
import json

from payhook.errors import InvalidNotification


_MAX_TIMESTAMP_SKEW = 300


def _header(headers, name):
    """Get one HTTP header without relying on a particular mapping type."""
    try:
        matches = [value for key, value in headers.items()
                   if isinstance(key, str) and key.lower() == name.lower()]
    except (AttributeError, TypeError):
        raise InvalidNotification("invalid headers")
    if len(matches) != 1 or not isinstance(matches[0], str):
        return None
    return matches[0]


def _matches(header_value, version, message, secret):
    if not isinstance(header_value, str):
        return False

    prefix = version + "="
    if not header_value.startswith(prefix):
        return False
    supplied = header_value[len(prefix):]
    if len(supplied) != hashlib.sha256().digest_size * 2:
        return False
    try:
        supplied_digest = bytes.fromhex(supplied)
        expected_digest = hmac.new(secret, message, hashlib.sha256).digest()
        return hmac.compare_digest(supplied_digest, expected_digest)
    except (TypeError, ValueError):
        return False


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    if not isinstance(raw_body, bytes):
        raise InvalidNotification("body must be bytes")

    timestamp = _header(headers, "X-Pay-Timestamp")
    if (timestamp is None or not timestamp or not timestamp.isascii()
            or not timestamp.isdecimal()):
        raise InvalidNotification("invalid timestamp")
    try:
        timestamp_value = int(timestamp)
        if abs(timestamp_value - now) > _MAX_TIMESTAMP_SKEW:
            raise InvalidNotification("stale timestamp")
    except (TypeError, ValueError, OverflowError):
        raise InvalidNotification("invalid timestamp")

    try:
        event = json.loads(
            raw_body.decode("utf-8"),
            parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)),
        )
    except (TypeError, ValueError, UnicodeError):
        raise InvalidNotification("invalid JSON")
    if not isinstance(event, dict):
        raise InvalidNotification("notification must be an object")

    event_id = event.get("event_id")
    account_id = event.get("account_id")
    amount_minor = event.get("amount_minor")
    currency = event.get("currency")
    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("invalid event_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("invalid account_id")
    if (not isinstance(amount_minor, int) or isinstance(amount_minor, bool)
            or amount_minor < 0):
        raise InvalidNotification("invalid amount_minor")
    if (not isinstance(currency, str) or len(currency) != 3
            or not currency.isascii() or not currency.isalpha()
            or not currency.isupper()):
        raise InvalidNotification("invalid currency")

    signed_prefix = timestamp.encode("ascii") + b"."
    v1_matches = _matches(
        _header(headers, "X-Pay-Signature"), "v1",
        signed_prefix + raw_body, secret,
    )
    try:
        receipt_message = signed_prefix + event_id.encode("utf-8")
    except UnicodeError:
        raise InvalidNotification("invalid event_id")
    receipt_matches = _matches(
        _header(headers, "X-Pay-Receipt"), "r0", receipt_message, secret,
    )
    if not (v1_matches or receipt_matches):
        raise InvalidNotification("signature did not match")

    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }
"}
